def format_bytes(n):
    """Return a human-readable size string like '1.5 KB'."""
    if n < 0:
        raise ValueError("Negative byte size")
    units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB']
    i = 0
    while n >= 1024 and i < len(units) - 1:
        n /= 1024.0
        i += 1
    if i == 0:
        return f"{n} {units[i]}"
    return f"{n:.1f} {units[i]}"
